import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import json

# Set seaborn style for professional look
sns.set_theme(style="whitegrid")
plt.rcParams.update({'font.size': 10, 'figure.figsize': (10, 6)})

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

def generate_report():
    # 1. Load data
    df = pd.read_csv('/app/benchmark/data.csv')

    # KPIs Calculation
    median_col_index = df['cost_of_living_index'].median()
    avg_rent_to_salary = df['rent_to_salary_ratio_pct'].mean()
    purchasing_power_gap = df['local_purchasing_power_index'].max() - df['local_purchasing_power_index'].min()
    max_crisis_tier = df['cost_crisis_tier'].max()
    high_crisis_count = len(df[df['cost_crisis_tier'] == max_crisis_tier])
    avg_inflation = df['annual_inflation_rate_2025_pct'].mean()

    # 2. Generate Visualizations

    # Chart 1: Regional Comparison (Cost of Living vs Rent Index)
    fig1, ax1 = plt.subplots(figsize=(12, 6))
    sns.scatterplot(data=df, x='cost_of_living_index', y='rent_index', hue='region', size='population_city_millions', sizes=(50, 400), alpha=0.7, ax=ax1)
    ax1.set_title('Regional Comparison: Cost of Living vs. Rent Index', fontsize=14, pad=15)
    ax1.set_xlabel('Cost of Living Index (NY = 100)')
    ax1.set_ylabel('Rent Index (NY = 100)')
    ax1.legend(bbox_to_anchor=(1.05, 1), loc='upper left')
    chart1_b64 = fig_to_base64(fig1)

    # Chart 2: Affordability - Top 15 Cities with Highest Rent Burden
    fig2, ax2 = plt.subplots(figsize=(12, 6))
    top_rent_burden = df.nlargest(15, 'rent_to_salary_ratio_pct')
    sns.barplot(data=top_rent_burden, x='rent_to_salary_ratio_pct', y='city', hue='region', ax=ax2, dodge=False)
    ax2.set_title('Top 15 Cities by Rent-to-Salary Ratio (%)', fontsize=14, pad=15)
    ax2.set_xlabel('Rent-to-Salary Ratio (%)')
    ax2.set_ylabel('')
    ax2.legend(bbox_to_anchor=(1.05, 1), loc='upper left')
    chart2_b64 = fig_to_base64(fig2)

    # Chart 3: Crisis Tier Profiling
    tier_summary = df.groupby(['cost_crisis_tier', 'crisis_label'])[['cost_of_living_index', 'rent_to_salary_ratio_pct', 'local_purchasing_power_index']].mean().reset_index()
    tier_summary_melted = tier_summary.melt(id_vars=['cost_crisis_tier', 'crisis_label'], value_vars=['cost_of_living_index', 'rent_to_salary_ratio_pct', 'local_purchasing_power_index'])

    fig3, ax3 = plt.subplots(figsize=(12, 6))
    sns.barplot(data=tier_summary_melted, x='crisis_label', y='value', hue='variable', ax=ax3)
    ax3.set_title('Average Indicators by Crisis Tier', fontsize=14, pad=15)
    ax3.set_xlabel('Crisis Tier')
    ax3.set_ylabel('Index / Percentage')
    plt.xticks(rotation=45, ha='right')
    ax3.legend(title='Indicator', bbox_to_anchor=(1.05, 1), loc='upper left')
    chart3_b64 = fig_to_base64(fig3)

    # Chart 4: Inflation and Oil Shock Exposure
    fig4, ax4 = plt.subplots(figsize=(10, 6))
    sns.boxplot(data=df, x='oil_shock_exposure', y='annual_inflation_rate_2025_pct', order=['Low', 'Medium', 'High'], ax=ax4)
    sns.stripplot(data=df, x='oil_shock_exposure', y='annual_inflation_rate_2025_pct', order=['Low', 'Medium', 'High'], color='black', alpha=0.5, jitter=True, ax=ax4)
    ax4.set_title('Inflation Rate Distribution by Oil Shock Exposure', fontsize=14, pad=15)
    ax4.set_xlabel('Oil Shock Exposure')
    ax4.set_ylabel('Annual Inflation Rate 2025 (%)')
    chart4_b64 = fig_to_base64(fig4)

    # 3. HTML Generation
    html_content = f"""
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>Global Cost of Living Crisis Index 2026</title>
        <style>
            :root {{
                --primary: #2c3e50;
                --secondary: #34495e;
                --accent: #3498db;
                --bg: #f8f9fa;
                --text: #333;
                --border: #e0e0e0;
            }}
            body {{
                font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                line-height: 1.6;
                color: var(--text);
                background-color: var(--bg);
                margin: 0;
                padding: 0;
            }}
            .container {{
                max-width: 1200px;
                margin: 0 auto;
                padding: 40px 20px;
                background-color: white;
                box-shadow: 0 0 20px rgba(0,0,0,0.05);
            }}
            header {{
                text-align: center;
                margin-bottom: 50px;
                padding-bottom: 30px;
                border-bottom: 2px solid var(--accent);
            }}
            h1 {{
                color: var(--primary);
                font-size: 2.5em;
                margin-bottom: 10px;
            }}
            h2 {{
                color: var(--primary);
                border-bottom: 1px solid var(--border);
                padding-bottom: 10px;
                margin-top: 40px;
            }}
            h3 {{
                color: var(--secondary);
            }}
            .subtitle {{
                font-size: 1.2em;
                color: var(--secondary);
                font-style: italic;
            }}
            .kpi-container {{
                display: flex;
                flex-wrap: wrap;
                gap: 20px;
                margin-bottom: 40px;
                justify-content: space-between;
            }}
            .kpi-card {{
                background: #fff;
                border: 1px solid var(--border);
                border-radius: 8px;
                padding: 20px;
                flex: 1;
                min-width: 180px;
                text-align: center;
                box-shadow: 0 4px 6px rgba(0,0,0,0.05);
            }}
            .kpi-value {{
                font-size: 2em;
                font-weight: bold;
                color: var(--accent);
                margin: 10px 0;
            }}
            .kpi-label {{
                font-size: 0.9em;
                color: var(--secondary);
                text-transform: uppercase;
                letter-spacing: 1px;
            }}
            .kpi-desc {{
                font-size: 0.8em;
                color: #777;
                margin-top: 5px;
            }}
            .chart-container {{
                margin: 30px 0;
                text-align: center;
                border: 1px solid var(--border);
                padding: 20px;
                border-radius: 8px;
                background: white;
            }}
            .chart-container img {{
                max-width: 100%;
                height: auto;
            }}
            .table-container {{
                overflow-x: auto;
                margin: 20px 0;
            }}
            table {{
                width: 100%;
                border-collapse: collapse;
